// Loaded as a classic script after client.js to use the signed-in store workspace.
async function dataCenter(){
 $('#view').innerHTML=page('Your store data.','Products, customers, orders, order items and payments are saved on the server.')+'<div class="panel" id="database-summary">Loading your database…</div>';
 try{const s=await api('/database');if(view!=='database')return;
 $('#database-summary').innerHTML=`<div class="panel-head"><h3>Database connected</h3><span class="pill">Schema v${esc(s.schemaVersion)}</span></div><p>${esc(s.engine)} · Your store records are isolated from other supermarket accounts.</p><div class="stats">${Object.entries(s.counts).map(([k,v])=>`<div class="stat"><div class="stat-label">${esc(k.replace('_',' '))}</div><div class="value">${v}</div></div>`).join('')}</div><a class="btn" href="/api/database/export">Download store data (JSON)</a><div class="note warning">This export includes customer phone numbers, addresses and messages. Store it privately. It excludes passwords, login sessions and WhatsApp API tokens. Export restoration is not implemented.</div>`;
 $('#view').insertAdjacentHTML('beforeend',`<div class="grid-two"><div class="panel"><h3>Prepare your first records</h3><p>Download the column templates, collect your store details, then use Products and Customers to add records. CSV bulk import is not enabled yet.</p><div class="card-row"><div><b>Product template</b><small>Name, brand, unit, price, stock and low-stock threshold</small></div><button class="btn small secondary" id="product-template">Download</button></div><div class="card-row"><div><b>Customer template</b><small>Phone, address, postcode and recorded messaging consent</small></div><button class="btn small secondary" id="customer-template">Download</button></div></div><div class="panel"><h3>How your records work together</h3><ul class="connect-bullets"><li>Each record belongs to your signed-in store.</li><li>Orders preserve agreed item names, units and prices.</li><li>Order items store quantity and the price at ordering time.</li><li>Stock and order changes commit together.</li><li>Payment history preserves manual confirmation records.</li><li>Monetary database columns use integer paise.</li></ul></div></div><div class="panel"><h3>Payment history</h3>${table(['ORDER ID','RECORDED','AMOUNT','STATUS','SOURCE','REFERENCE'],s.paymentHistory.map(p=>row([esc(p.orderId),date(p.recordedAt),money(p.amountPaise/100),pill(p.status),esc(p.source),esc(p.reference)])))}</div>`);
 $('#product-template').onclick=()=>csv('product-template',[],['name','brand','unit','price','stock','lowStock']);
 $('#customer-template').onclick=()=>csv('customer-template',[],['name','phone','address','postcode','serviceConsent','marketingConsent','consentSource']);
 }catch(e){if($('#database-summary'))$('#database-summary').textContent=e.message}
}
